repaired_test:
"def test_delete_non_enterprise_plan_failure(api, base, monkeypatch):
    """
    Test that Base.delete() raises an exception for non-enterprise plans.
    """
    class MockResponse:
        def __init__(self, status_code):
            self.status_code = status_code

    def mock_delete(url):
        return MockResponse(404)

    monkeypatch.setattr(api, 'delete', mock_delete)

    with pytest.raises(Exception) as excinfo:
        base.delete()

    assert str(excinfo.value) == "Base.delete() requires an enterprise billing plan""
